def transform(grid):
    h,w=len(grid),len(grid[0])
    line=[r for r in range(h) if len(set(grid[r]))==1 and grid[r][0]!=0][0]
    out=[row[:] for row in grid]
    for i in range(h-1,-1,-1):
        for j in range(w):
            v=grid[i][j]
            if v==0 or i==line or out[i][j]!=v: continue
            out[i][j]=0
            a=i+1
            out[a][j]=v
            if a==line-1:
                for dc in (-1,1):
                    r,c=a-1,j+dc
                    while 0<=r<h and 0<=c<w:
                        out[r][c]=v; r-=1; c+=dc
    return out
